arguments.command:
python3 -I -c "
import csv, collections
rows=list(csv.DictReader(open('/app/dataset/temperature_logs.csv')))
def f(s): return float(s.replace(',','.'))
lim={'frozen':-10,'meat':4,'dairy':6,'dry':35}
byzone=collections.defaultdict(list)
for r in rows: byzone[r['zone'].lower()].append((r['timestamp'], f(r['temperature_c'])))
for z in byzone:
    v=sorted(byzone[z])
    bad=[(t,x) for t,x in v if x>lim[z]]
    print('ZONE',z,'limit',lim[z],'violations',len(bad))
    for t,x in bad: print('   ',t,x)
"

