arguments.command:
python3 -I -c "
import csv
cat={}
for r in csv.DictReader(open('/app/dataset/product_catalog.csv')):
    if r['product_id']: cat[r['product_id']]=r
ean={r['ean_code']:p for p,r in cat.items()}
d=[r for r in csv.DictReader(open('/app/dataset/warehouse_dispatches.csv')) if r['dispatch_id']]
print('weight mismatches (>2%):')
for r in d:
    pid=r['product_id']; pid=pid if pid in cat else ean.get(pid)
    uw=float(cat[pid]['unit_weight_kg']); q=int(r['quantity']); w=float(r['total_weight_kg'])
    if abs(uw*q-w)>max(0.02*max(w,1e-9),0.011):
        print('  ',r['dispatch_id'],r['timestamp'],pid,cat[pid]['name'],'q',q,'w',w,'expected',round(uw*q,2))
print('qty range:',min(int(r['quantity']) for r in d), max(int(r['quantity']) for r in d))
print('ts range:',min(r['timestamp'] for r in d), max(r['timestamp'] for r in d))
"

